func TestRobots(t *testing.T) {

	var runner day14.Runner

	data := []byte("p=0,4 v=3,-3\np=6,3 v=-1,-3\np=10,3 v=-1,2\np=2,0 v=2,-1\np=0,0 v=1,3\np=3,0 v=-2,-2\np=7,6 v=-1,-3\np=3,0 v=-1,-2\np=9,3 v=2,3\np=7,3 v=-1,2\np=2,4 v=2,-3\np=9,5 v=-3,-3")

	robots, err := runner.ParseInput(data)

	if err != nil {
		t.Fatalf("Should return err: %s\n", err)
	}

	expected := []utils.Point[struct{}]{
		{X: 3, Y: 5},
		{X: 5, Y: 4},
		{X: 9, Y: 0},
		{X: 4, Y: 5},
		{X: 1, Y: 6},
		{X: 1, Y: 3},
		{X: 6, Y: 0},
		{X: 2, Y: 3},
		{X: 0, Y: 2},
		{X: 6, Y: 0},
		{X: 4, Y: 5},
		{X: 6, Y: 6},
	}

	runner.Iteration(100, robots, 11, 7)

	for _, robot := range robots {
		if !slices.Contains(expected, robot.Position) {
			t.Fatalf("Unable to find %v in %v\n", robot.Position, expected)
		}
	}

}

func TestQuadrant(t *testing.T) {

	var runner day14.Runner

	data := []byte("p=0,4 v=3,-3\np=6,3 v=-1,-3\np=10,3 v=-1,2\np=2,0 v=2,-1\np=0,0 v=1,3\np=3,0 v=-2,-2\np=7,6 v=-1,-3\np=3,0 v=-1,-2\np=9,3 v=2,3\np=7,3 v=-1,2\np=2,4 v=2,-3\np=9,5 v=-3,-3")

	robots, err := runner.ParseInput(data)

	if err != nil {
		t.Fatalf("Should return err: %s\n", err)
	}

	expected := []utils.Point[struct{}]{
		{X: 3, Y: 5},
		{X: 5, Y: 4},
		{X: 9, Y: 0},
		{X: 4, Y: 5},
		{X: 1, Y: 6},
		{X: 1, Y: 3},
		{X: 6, Y: 0},
		{X: 2, Y: 3},
		{X: 0, Y: 2},
		{X: 6, Y: 0},
		{X: 4, Y: 5},
		{X: 6, Y: 6},
	}

	runner.Iteration(100, robots, 11, 7)

	for _, robot := range robots {
		if !slices.Contains(expected, robot.Position) {
			t.Fatalf("Unable to find %v in %v\n", robot.Position, expected)
		}
	}

	runner.Display(11, 7, robots, os.Stdout)

	res := runner.FindRobotInQuadrant(11, 7, robots)

	if res != 12 {
		t.Fatalf("Should return %d instead %d\n", 12, res)
	}

}

