func parseGrid(input string) map[utils.Point[struct{}]]struct{} {

	lines := strings.Fields(input)

	grid := make(map[utils.Point[struct{}]]struct{})

	for y, row := range lines {
		for x, char := range row {
			if char != '.' {
				grid[utils.Point[struct{}]{X: x, Y: y}] = struct{}{}
			}
		}
	}

	return grid
}

func BenchmarkPointerBased(b *testing.B) {

	var runner day14.Runner

	grid := parseGrid(data)
	visited := make(map[utils.Point[struct{}]]struct{})

	for point := range grid {
		for i := 0; i < b.N; i++ {
			counter := 0
			runner.FindAdjacentRecursivePointer(&counter, point, grid, visited)
		}
	}
}

func BenchmarkReturnBased(b *testing.B) {

	var runner day14.Runner

	grid := parseGrid(data)
	visited := make(map[utils.Point[struct{}]]struct{})

	for p := range grid {
		for i := 0; i < b.N; i++ {
			runner.FindAdjacentRecursive(p, grid, visited)
		}
	}
}
